function drawCircleNew(x, y, dia, RAT) { // RATIO [0.8, 0.2] start end fraction b&w per stripe, must be 1 in sum (0.8+0.2)
	const NM = NUM-1 + RAT[1]; // NUM = 11 -> 10.2 -> 10 b/w changes plus one last black 
	const TH = dia / NM;
	push()
	// blendModebeginClip();
	let yy = y - dia/2;
	for (let i = 0; i < NUM; i++, yy += TH) {
		const f = i/(NUM-1); // 0..1
		const H = TH * map(f, 0, 1, RAT[0], RAT[1]); 
		rect(x-dia/2, yy, dia, H);
	}
	endClip();
	// blendMode(DIFFERENCE); // not working, why?
	circle(x, y, dia);
	pop();
}
